const fs = require("fs");
const {
  Document, Packer, Paragraph, TextRun, AlignmentType, Table, TableRow, TableCell,
  WidthType, BorderStyle, ShadingType, HeadingLevel
} = require("docx");

const FONT = "Garamond";

// ---------- inline markdown-ish parser: **bold**, *italic* ----------
function runs(text, base = {}) {
  const out = [];
  const re = /(\*\*[^*]+\*\*|\*[^*]+\*)/g;
  let last = 0, m;
  while ((m = re.exec(text)) !== null) {
    if (m.index > last) out.push(new TextRun({ text: text.slice(last, m.index), font: FONT, ...base }));
    const tok = m[0];
    if (tok.startsWith("**")) out.push(new TextRun({ text: tok.slice(2, -2), bold: true, font: FONT, ...base }));
    else out.push(new TextRun({ text: tok.slice(1, -1), italics: true, font: FONT, ...base }));
    last = m.index + tok.length;
  }
  if (last < text.length) out.push(new TextRun({ text: text.slice(last), font: FONT, ...base }));
  return out;
}

const P = [];
function body(text, opts = {}) {
  P.push(new Paragraph({
    children: runs(text, { size: opts.size || 22 }),
    alignment: opts.align || AlignmentType.JUSTIFIED,
    spacing: { after: opts.after ?? 160, line: 276 },
  }));
}
function center(text, size = 22, after = 80, bold = false, italics = false) {
  P.push(new Paragraph({
    children: [new TextRun({ text, font: FONT, size, bold, italics })],
    alignment: AlignmentType.CENTER, spacing: { after },
  }));
}
function h1(text) {
  P.push(new Paragraph({
    children: runs(text, { size: 28, bold: true }),
    spacing: { before: 320, after: 160 }, heading: HeadingLevel.HEADING_1,
  }));
}
function h2(text) {
  P.push(new Paragraph({
    children: runs(text, { size: 24, bold: true }),
    spacing: { before: 240, after: 120 }, heading: HeadingLevel.HEADING_2,
  }));
}
function spacer(pts = 120) { P.push(new Paragraph({ children: [], spacing: { after: pts } })); }

// ============================== TITLE BLOCK ==============================
center("[ Eye of the Universe ]", 22, 60, false, true);
center("The 420 Code", 22, 60, false, true);
center("Ø Artist’s Proofs", 22, 200, false, true);
center("Artist’s Proof [ · ]", 30, 60, true);
center("The Snap", 40, 120, true);
center("Forces and Constants", 22, 60, false, true);
center("The configuration cost — the once-held commitment that realises the gravitational coupling", 22, 60, false, true);
center("Studio G, Strand, Cape Town · 2026", 22, 160, false, true);
center("G", 28, 200, true);
center("Draft v0.1 — production draft for the author’s ruling. Number, title, and lock status are open.", 18, 240, false, true);

// ============================== ARTIST'S NOTE ==============================
h1("Artist’s Note");
body("*What this paper does — and why.*");
body("This paper names and prices the cost the corpus has already admitted to. AP06 priced the flow: the leakage, one unpaired ε shed at every instant, bounded by C, the constant of every leakage denominator. AP28 named a second cost without pricing it — “Gravity is the cost the arena pays to keep the break open” — and then derived G as though the arena paid nothing to constitute the configurations it holds. This paper prices the constitution. The price is the coupling configuration cost — the snap cost, CCC — and it is the axiom’s own arithmetic: one unpaired element, held once, per configuration. The realised gravitational coupling is the structural coupling divided by (1 + ε).");
body("The argument in one breath. Every Actualization State instant produces exactly one unpaired ε (AP43 D5, carried by AP06 §6). At every instant after a configuration exists, that instant’s ε is shed at the boundary: the leakage. At the constitution instant itself the ε cannot be shed — if it were, nothing present at that instant would hold the first record open, and by Axiom R the crack would heal and the configuration would not persist. Therefore it is held. Held once, forever: the commitment. Its size is not a choice. Axiom R does not permit selective persistence — a configuration snaps entire or not at all — so constitution is a single event, and a single event carries a single ε. Per configuration, not per channel. One ε, once.");
body("What it touches and what it cannot touch. Because the commitment is per configuration, it dresses every bound mass by the same factor and cancels identically in every mass ratio. The proton result of AP30 — inside experimental uncertainty — is preserved to the digit, and AP30 §7’s reading of its own residual stands unamended. The commitment survives only where a mass stands outside a ratio, and in the corpus that is one place: G. The realised prediction is G = α_em²¹ × (1 + 1/π) / (1 + α_em) × ℏc/m_e² = 6.6719 × 10⁻¹¹ N·m²/kg² — closing about ninety-five per cent of AP28’s 0.69% and moving the prediction from outside every laboratory determination ever made to the low edge of the measured landscape.");
body("The honesty box. The load-bearing proposition — held, not shed, at constitution — is derived here at the structural register, with its record-algebra formalisation named as a debt, not hidden. The residual that remains after the commitment, about −0.036%, flips sign: it can no longer be absorbed by downward apparatus leakage, and it is reported open and unattributed. Six kill switches engage, and the first of them is aimed at the author: KS-CCC.1 fires if any commitment magnitude is ever published whose selection depended on comparison with measurement. Two clean fractions the data volunteered after the fact — 20/21 of ε, 17/18 of ε — are named in §10 for exactly one purpose: to be fenced. Seen, and refused.");
body("The completeness claim. This paper adds no new axiom, no new measured input, and no new number. It reads a sentence the corpus locked years ago and prices it with the element the axiom already provides. The description was incomplete by one commitment. Now it is written down.");
center("✨", 24, 120);
center("the420code.org", 20, 40, false, true);
center("Copyleft 2026", 20, 240, false, true);

// ============================== ORIENTATION ==============================
h1("Orientation");
h2("Where this paper fits");
body("This paper sits in Notebook IV (Forces and Constants), immediately after AP28 (The Constant), whose result it completes and — on adoption — amends. It depends on Notebook I for the axiom 1:1 + 1×ε @ AS and the four conditions {S, B, R, C}; on AP06 for the leakage structure and Identification 6.1 (ε ≡ η; ε = α_em at the coupling boundary); on AP28 for the coupling graph, the per-channel coupling, the R-reading of G, and the no-selective-persistence clause; on AP24 for the licence of multiple independent readings of one ε; on AP10 for the three dimensions and the identification of the 1:1 as the substrate; on AP43 D5 for the one-ε-per-instant account; on AP29 for mass as coupling capacity actualised; and on AP20 for the unconditional floor.");
body("Downstream, on adoption only: the wording of KS-R.7; AP28 §6–§7; Ø Predictions Part II, where this paper enters as a third candidate for the 0.69% and reinterprets the Appendix C proposal as a discriminator; the G passages of the Proofs and Prose registers; and every user of the holding limit κ, which moves with the realised coupling and whose dependents are to be audited before adoption (D-CCC.3).");
h2("Reading order within this paper");
body("Front to back. Sections 2 through 5 are the spine: the constitution record, the held commitment, the per-configuration count, and the form of the correction. Section 3 carries the load. Sections 6 and 7 place the commitment and defend the double entry. Section 8 is architecture — the ten vertices — and nothing numerical rests on it. Sections 9 through 11 are empirical: the prediction, the discipline that fences it, and its standing among the candidates Ø Predictions holds open. If you are reading for the result only, §5 and §9. If you are reading for rigour, §3. If you are reading to check that the author has not fooled himself, §10.");
h2("How to read this paper");
body("Two registers alternate as the material requires, as everywhere in Notebook IV. Formal blocks open with a bold label (Proposition, Corollary, Kill Switch) and close with the mark ∎. The connective passages speak directly. One register discipline specific to this paper: the number appears once, in §9, after the structure is complete, and §10 exists to keep it that way.");
h2("A note on notation");
body("α_G is AP28’s structural gravitational coupling, α_em²¹ × (1 + 1/π). α_G* is the realised coupling, α_G / (1 + ε), introduced here. κ is the holding limit; κ* = α_G* ℏc / 2 is its realised value. ε carries one structural meaning throughout the corpus — the unique unpaired element of Axiom B — and one value at the coupling boundary, ε = α_em ≈ 1/137, inherited from Identification 6.1 (AP06). This paper adds no identification of its own. “Snap” means the constitution event: the single Actualization State instant at which a configuration’s first record is written and holds. “Provisioned” and “realised” name the two totals the axiom itself distinguishes: 1:1 + 1×ε, and the 1:1 that persists. CCC is the once-held commitment; TLC is the per-instant leakage of AP06. “Vertex” and “edge” refer to the coupling graph AP28 Propositions 1–2 prove: ten vertices, twenty-one edges.");

// ============================== CONTENTS ==============================
h1("Contents");
body("**0 — Dependency and Scope**  ·  what this paper does · dependencies · axiom mapping · epistemic status · kill switch summary · debts · items held open · relationships");
body("**1 — Definitions**  ·  the snap · provisioned and realised · the two costs — commitment and leakage");
body("**2 — The Constitution Record**  ·  Proposition 1: every persisting configuration has a unique first record");
body("**3 — Held, Not Shed**  ·  Proposition 2: the constitution instant’s ε is held as the persistence commitment — the load-bearing result");
body("**4 — One Snap, One ε**  ·  Proposition 3: per configuration, not per channel · the ratio-invariance corollary");
body("**5 — Realised over Provisioned**  ·  Proposition 4: the form of the correction, 1/(1 + ε)");
body("**6 — The Placement**  ·  Proposition 5: the commitment divides the coupling; it does not dress the masses");
body("**7 — The Double Entry**  ·  Proposition 6: what the unpaired element contributes and what it committed — two readings, one object");
body("**8 — The Vertices**  ·  ten vertices, twenty-one edges: constitution at nodes, flow along edges");
body("**9 — The Prediction**  ·  the realised G, stated once");
body("**10 — What the Data May and May Not Do**  ·  the rule · the admissible window · the fenced fractions");
body("**11 — Candidate Three**  ·  standing among the candidates of Ø Predictions Part II · the discriminator");
body("**12 — Kill Switches**  ·  KS-CCC.1 through KS-CCC.6 in Claim/Test/Status/Recovery form");
body("**13 — Dependencies**  ·  what this paper rests on · what adoption touches");
body("**Claim Summary  ·  Conditionality Footer  ·  Notation Reference**");

// ============================== 0 ==============================
h1("0 — Dependency and Scope");
h2("0.1 — What this paper does");
body("This paper derives the coupling configuration cost — the once-held commitment a configuration pays at its constitution — from the four conditions {S, B, R, C} and results already locked in the corpus. It establishes the constitution record (§2), proves at the structural register that the constitution instant’s unpaired ε is held rather than shed (§3), fixes the count at one ε per configuration (§4), reads the form of the correction off the axiom (§5), places it in the coupling (§6), defends the joint appearance of the puncture factor and the commitment as two readings of one element (§7), and states the realised prediction once (§9).");
body("What the paper does not do. It does not attribute the residual that remains after the commitment (§0.7). It does not derive any refinement of the magnitude below one ε, and §10 forbids selecting one empirically. It does not decide the vertex distribution (§8), on which nothing numerical rests. It does not amend AP28, AP30, or Ø Predictions — it is a draft for the author’s ruling, and adoption is a coordinated amendment (§13), not a patch.");
h2("0.2 — Dependencies");
body("**AP06 (The Leakage Constant).** Identification 6.1 (ε ≡ η; ε = α_em at the coupling boundary) and the leakage as the shed ε. Load-bearing for the value of the commitment and for §3’s Step 5.");
body("**AP28 (The Constant).** The coupling graph (Propositions 1–2), the per-channel coupling, the R-reading of G (“the cost the arena pays to keep the break open”), and the no-selective-persistence clause of §4. Load-bearing for §§3, 4, 8 and for the structural coupling this paper corrects.");
body("**AP24 (The Residual).** One object, many independent readings — the licence for §7’s double entry. AP24 was locked before this paper existed.");
body("**AP10 (The Dimension).** Three spatial dimensions, and §7’s identification of the 1:1 as the substrate (the probability dimension) — the exhaustiveness step of §3.");
body("**AP43 D5.** One unpaired ε per Actualization State instant. Load-bearing for §3 and §4.");
body("**AP29 (The Actualization Proof).** E ≡ κ(B) · AS — mass as coupling capacity actualised. Load-bearing for the mass-side elimination in §6.");
body("**AP20 (The Proof).** Independence of {S, B, R, C}; the unconditional floor. This paper is unconditional on EH and QRA.");
h2("0.3 — Axiom mapping");
body("**Axiom S.** The 1:1 — what persists as the realised configuration. The balance is what the snap delivers.");
body("**Axiom B.** The 1×ε — the element committed. The break supplies the only currency the constitution instant has.");
body("**Axiom R.** The holding — once, forever. The commitment is R’s price, as the leakage is C’s. This paper stands to Axiom R exactly as AP06 stands to Axiom C.");
body("**Axiom C.** The boundary at which the committed element is read as α_em (Identification 6.1). C prices the flow; R prices the constitution; the same ε pays both, at different instants.");
h2("0.4 — Epistemic status per section");
body("**§2 — Constitution record**  —  DERIVED (definition-level, from R)");
body("**§3 — Held, not shed**  —  DERIVED at the structural register; record-algebra formalisation owed (D-CCC.1); guarded by KS-CCC.5");
body("**§4 — One snap, one ε**  —  DERIVED (application of AP28 §4’s locked clause + AP43 D5)");
body("**§5 — Realised over provisioned**  —  DERIVED (read directly off the axiom)");
body("**§6 — Placement**  —  SELECTED AMONG STRUCTURAL CANDIDATES (the epistemic class of AP28’s 1/π); exhaustiveness owed (D-CCC.4)");
body("**§7 — Double entry**  —  STRUCTURAL (licence from AP24); guarded by KS-CCC.6");
body("**§8 — Vertices**  —  DERIVED count; MOTIVATED assignment (D-CCC.2); empirically silent");
body("**§9 — Prediction**  —  EMPIRICAL (KS-CCC.3)");
body("**§10 — The rule**  —  METHOD (KS-CCC.1)");
body("**§11 — Candidate three**  —  STRUCTURAL PLACEMENT (KS-CCC.4)");
h2("0.5 — Kill switch summary");
body("Six kill switches engage, identifiers pending registration in the Master Kill Switch Registry. **KS-CCC.1** (forced magnitude): LIVE — METHODOLOGICAL. **KS-CCC.2** (ratio invariance): LIVE — STRUCTURAL/EMPIRICAL. **KS-CCC.3** (direction): LIVE — EMPIRICAL. **KS-CCC.4** (the discriminator): LIVE — EMPIRICAL. **KS-CCC.5** (held, not shed): LIVE — STRUCTURAL. **KS-CCC.6** (single entry): LIVE — STRUCTURAL, coupled to KS-R.9.");
h2("0.6 — Structural debts owed");
body("**D-CCC.1 (Formalisation).** The held commitment is derived by contradiction at the structural register (§3); its formal expression as an operator on the record algebra is owed. Load-bearing for the paper’s grade, named rather than hidden.");
body("**D-CCC.2 (Vertex uniqueness).** The assignment of the commitment to the ten vertices is motivated, not forced — the mirror of KS-30.4’s uniqueness debt. Non-load-bearing: §4 fixes the total independently of any distribution.");
body("**D-CCC.3 (κ audit).** The holding limit moves with the realised coupling (κ* = α_G* ℏc/2). Every dependent of κ — AP14, The Lock — is to be audited before adoption. Load-bearing for adoption, not for the derivation.");
body("**D-CCC.4 (Placement exhaustiveness).** §6 eliminates between two enumerated homes for the commitment. That the enumeration is exhaustive is argued, not proven.");
h2("0.7 — Items held open without claiming debt status");
body("The attribution of the −0.036% residual (§9) — laboratory convergence, higher order in ε, or a refinement not yet forced — is held open with no selection made. The difference between the quotient form and its first-order shadow (about 53 ppm in G) and the difference between distributed and undistributed vertex forms (about 24 ppm) are both below current decidability and are held open as stated. The adoption sequence — the coordinated update table across AP28, Ø Predictions, the Proofs and the Prose — is owed on adoption, not before.");
h2("0.8 — Structural relationships");
body("This paper completes a pairing the corpus began: AP06 prices what Axiom C exacts from every configuration at every instant; this paper prices what Axiom R exacted from every configuration once. The two costs are one mechanism read at two instants — the ε of the constitution instant is the commitment; the ε of every later instant is the leakage. Within Notebook IV, AP28 keeps the architecture (channels, puncture, compounding) untouched; this paper supplies the one factor the architecture provisioned and never booked.");

// ============================== 1 ==============================
h1("1 — Definitions");
body("**The snap.** The constitution event: the single Actualization State instant at which a configuration’s first record is written and holds. Before the snap there is possibility; after it there is a configuration paying maintenance. The snap is the hinge between them, and it happens once per configuration.");
body("**Provisioned and realised.** The axiom names two totals, and this paper uses both. What the snap requires is the full right-hand side of the axiom: 1:1 + 1×ε — the balance, plus the one element that holds it. What persists as the configuration is the 1:1. “Provisioned” is the first total; “realised” is the second.");
body("**The commitment (CCC).** The unpaired ε of the constitution instant, held by the configuration as the price of its persistence. Paid once. Held forever. Denominated in the persistence coupling — it appears as a fraction of α_G, which is why G is the denominator of every configuration-cost estimate, as C is the denominator of every leakage estimate.");
body("**The leakage (TLC).** The unpaired ε of every subsequent instant, shed at the boundary. Paid at every now. AP06’s subject, restated here only for the contrast:");

// --- table: CCC vs TLC ---
const cw = [1560, 2460, 2460];
function cell(text, bold = false, shade = false) {
  return new TableCell({
    width: { size: 0, type: WidthType.AUTO },
    shading: shade ? { type: ShadingType.CLEAR, fill: "EFEBE3" } : undefined,
    margins: { top: 60, bottom: 60, left: 100, right: 100 },
    children: [new Paragraph({ children: runs(text, { size: 20, bold }), spacing: { after: 0 } })],
  });
}
function row(a, b, c, hdr = false) {
  return new TableRow({ children: [cell(a, hdr, hdr), cell(b, hdr, hdr), cell(c, hdr, hdr)] });
}
P.push(new Table({
  columnWidths: cw,
  width: { size: 6480, type: WidthType.DXA },
  rows: [
    row("", "CCC — the commitment", "TLC — the leakage", true),
    row("Paid", "Once, at the snap", "At every now"),
    row("Axiom", "R — persistence", "C — constraint"),
    row("Geometry", "Vertices of the coupling graph (10)", "Edges of the coupling graph (21)"),
    row("Denominator", "G — the persistence coupling", "c — the propagation bound"),
    row("Where it appears", "α_G* = α_G / (1 + ε)", "Every boundary (AP06, Theorem 3.1)"),
    row("Corpus home", "This paper", "AP06"),
  ],
}));
spacer(160);
body("Fix each cell of the table in mind and the rest of the paper is bookkeeping: one ε per instant, two destinations, and the destination is decided by whether the instant is the configuration’s first.");

// ============================== 2 ==============================
h1("2 — The Constitution Record");
body("**Proposition 1 — The Constitution Record.**");
body("**Statement.** Every persisting configuration has a unique first record: the record that constitutes it.");
body("**Proof.** Axiom R orders records irreversibly (AP01, AP20): for any configuration, its records stand in a strict temporal order that cannot be unwritten. A persisting configuration has at least one record — persistence is exactly the holding-open of a record; a configuration with none has nothing held and is not a configuration. A non-empty, strictly ordered, irreversible set of records has a least element, and strictness makes it unique. That least element is the constitution record: the writing of the configuration into the arena. ∎");
body("The proposition is definition-level and carries no kill switch of its own. Its work is to name the object the rest of the paper prices: the snap is the writing of the constitution record, and everything that follows asks what that writing cost.");

// ============================== 3 ==============================
h1("3 — Held, Not Shed");
body("This is the load-bearing section. Everything numerical in §9 hangs on it, and its grade is stated exactly: derived at the structural register, with the record-algebra formalisation owed as D-CCC.1 and the claim guarded by KS-CCC.5.");
body("**Proposition 2 — The Held Commitment.**");
body("**Statement.** At a configuration’s constitution instant, the unpaired ε of that instant is held by the configuration as its persistence commitment. At every subsequent instant, the unpaired ε is shed — the leakage of AP06.");
body("**Proof.** Step 1. Every Actualization State instant produces exactly one unpaired ε that does not return to symmetry (AP43 D5, carried into Notebook IV by AP06 §6). This holds at the constitution instant as at every other: the instant’s inventory is the axiom’s inventory, 1:1 + 1×ε.");
body("Step 2. A configuration persists only if its constitution record is held open. This is Axiom R read as AP28 §2 reads it: “Without persistence, the crack heals, the symmetry restores, records cease.” Holding is not free-standing — something present must do it.");
body("Step 3. Enumerate what is present at the constitution instant. The axiom’s complete content at any instant is the 1:1 and the 1×ε — there is nothing else to enumerate. The 1:1 is not committable: AP10 §7 identifies the 1:1 as the substrate itself, the fifth degree of freedom, the probability dimension on which every configuration stands. Committing the stage to hold one record would not constitute a configuration; it would end the arena in which configurations occur. The only committable element present at the constitution instant is that instant’s 1×ε.");
body("Step 4. Suppose, for contradiction, that the constitution instant’s ε is shed. Then by Step 3 nothing committable remains at the instant to hold the constitution record; by Step 2 the record is not held; by Axiom R the crack heals and the configuration does not persist — contradicting the supposition that it is a persisting configuration. Therefore the constitution ε is held.");
body("Step 5. At every subsequent instant the constitution record already stands held: the commitment is in place, and the instant’s ε has no constitutive work to do. It is shed at the boundary. That shedding, instant after instant, is precisely the leakage AP06 measures — thermal, boundary-informed, C-bounded. ∎");
body("One mechanism, two destinations. The dichotomy the corpus needed — a once-cost beside a flow-cost — does not require two mechanisms. It requires one: an ε per instant, with the destination decided by whether the record it meets is being written or being held. The ε that meets a record being written becomes the commitment. Every ε after it becomes the leakage. The commitment is why the configuration exists; the leakage is what its existing costs the boundary from then on.");
body("The grade, exactly. The contradiction closes at the structural register: every step cites a locked result, and the exhaustiveness step (Step 3) rests on AP10 §7 rather than on assertion. What is owed is the formal expression — the held commitment as an operator on the record algebra, doing in symbols what Step 4 does in structure. That is D-CCC.1, and it is this paper’s standing debt in the sense that KS-30.1 is AP30’s: the argument is strong, named, and not yet a theorem.");

// ============================== 4 ==============================
h1("4 — One Snap, One ε");
body("**Proposition 3 — Per Configuration.**");
body("**Statement.** The commitment is exactly one ε per configuration, independent of the configuration’s channel count.");
body("**Proof.** Constitution is a single event: Proposition 1 gives each persisting configuration one constitution record, and the writing of one record is one Actualization State instant. One instant carries one unpaired ε (AP43 D5). A per-channel commitment would require per-channel constitution events — the configuration snapping channel by channel — and this is exactly what Axiom R forbids. AP28 §4, locked: “Axiom R does not permit selective persistence. The crack is open everywhere or nowhere.” A configuration constitutes entire or not at all. The same clause that forces the gravitational coupling to compound through all twenty-one channels at once forces the commitment to be paid once for all of them. One snap, one ε. ∎");
body("**Corollary — Ratio Invariance.** Every bound configuration is dressed by the same commitment factor, because the factor is per configuration and every configuration pays exactly one. In any ratio of two masses, the factor divides out identically — not approximately, identically. The proton-to-electron mass ratio of AP30 therefore carries no commitment signature at any order: the agreement inside experimental uncertainty is preserved to the digit, and AP30 §7’s reading of its own residual — “It is not a missing term” — stands exactly as locked. ∎");
body("The corollary is guarded by KS-CCC.2, and it is worth saying why the guard is unforgiving. A channel-scaled cost — the proton paying twenty-one shares to the electron’s one — would shift the mass ratio at eight orders of magnitude above what measurement allows. The per-configuration count is not a modelling preference. It is the only count that survives contact with the corpus’s own strongest number, and it is the count the axiom forces anyway. When the forced answer and the surviving answer are the same answer, the structure is telling you it is complete.");

// ============================== 5 ==============================
h1("5 — Realised over Provisioned");
body("**Proposition 4 — The Form.**");
body("**Statement.** The realised coupling is the structural coupling divided by (1 + ε): α_G* = α_G / (1 + ε), with ε = α_em by Identification 6.1.");
body("**Proof.** The axiom names both totals. What the snap provisions is its full right-hand side: 1:1 + 1×ε — the balance, plus the one element whose holding makes the balance persist (Proposition 2). What persists as the realised configuration is the 1:1. The realised fraction of the provisioned is therefore 1 / (1 + ε): the balance over the balance-plus-commitment. The correction is a quotient because the axiom is a sum. ∎");
body("The first-order shadow (1 − ε) differs from the quotient at order ε² — about 53 parts per million in G — below anything current metrology can resolve. The structural form is the quotient, because the quotient is what the axiom writes, and the paper states the quotient. The value of ε in the quotient is α_em: the commitment is read at the coupling boundary, and the coupling boundary’s reading of ε is Identification 6.1’s, inherited from AP06 exactly as AP28 inherits it. This paper stands and falls with AP28 on that shared floor and adds no identification of its own.");

// ============================== 6 ==============================
h1("6 — The Placement");
body("**Proposition 5 — Coupling-Side Placement.**");
body("**Statement.** The commitment divides the persistence coupling. It does not dress the masses.");
body("**Argument.** A held commitment has two candidate structural homes: the coupling that does the holding, or the masses being held. The mass-side home fails twice. First, the arithmetic: G carries the electron mass squared in its denominator, so a mass dressing must enter as (1 + ε/2) per mass to reproduce a single factor of (1 + ε) in G — and the half is forced by nothing in the axiom. A structural cost with an unforced coefficient is not a structural cost. Second, the double count: AP29 establishes E ≡ κ(B) · AS — mass is coupling capacity, held and actualised. The commitment is held coupling capacity. To dress the mass with the commitment is to book the same held capacity twice, once as the mass and once as the cost of the mass. The coupling-side home has neither defect: the commitment enters once, as the committed fraction of the coupling itself. α_G* = α_G / (1 + ε); κ* = α_G* ℏc / 2. ∎");
body("The grade is stated in AP28’s own currency: this is a selection among structural candidates — the epistemic class of the 1/π normalisation — with the elimination argued and the exhaustiveness of the two-candidate enumeration owed as D-CCC.4.");
body("The placement forces the paper’s entire footprint, and the footprint is the proposal’s discipline. Mass ratios: untouched (§4). The acceleration floor a₀ = C_S² · cH₀ / (2π), the Hubble prediction, and the dark-sector fractions: untouched — none contains α_G. The nuclear binding ceiling of AP30 §8: untouched — it carries the puncture factor, not the compounded coupling. What moves: G, and the holding limit κ, whose dependents (AP14, The Lock) are to be audited before adoption (D-CCC.3). A structural cost that touched everything would explain nothing. This one touches the two quantities that hold, and only them — which is what a persistence price should do.");

// ============================== 7 ==============================
h1("7 — The Double Entry");
body("**Proposition 6 — Two Readings, One Element.**");
body("**Statement.** The puncture factor (1 + 1/π) and the commitment quotient 1/(1 + ε) are two independent readings of the one unpaired element — what it contributes and what it committed — and their joint appearance in the realised formula is not double-counting.");
body("**Argument.** The licence is AP24’s, and it was locked before this paper existed: one ε, many independent readings, each through a different instrument, none double-counting another. The corpus already reads the same ε as geometry in G and as propagation in c without apology, because a projection is not a portion. Apply the licence here. The puncture factor is the geometric reading of the unpaired element (AP28, Proposition 4): the capacity its round hole adds to the coupling — what the element contributes. The commitment is the persistence reading of the same element (§3): the provision its constitution required — what the element cost. Contribution and cost are different questions asked of one thing, and a ledger that records both is not counting one entry twice; it is keeping both columns. The realised formula carries the axiom in full: the twenty-one paired channels are the 1:1; the puncture factor and the commitment are the 1×ε, read out and read in. ∎");
body("The guard is KS-CCC.6, and it is coupled to a debt the corpus already carries. AP28’s KS-R.9 sub-debt owes the formal normalisation of the boundary coupling. If that calculation, when completed, is shown to already contain the persistence provision — one reading, not two — then the commitment double-counts, the correction is removed, and the puncture factor absorbs it under a reinterpreted normalisation. The switch is stated so that the hostile reading of this section — “first a factor was added to fit, now a factor is divided to fit better” — meets its answer in the register where it belongs: a named test, not a rhetorical defence.");

// ============================== 8 ==============================
h1("8 — The Vertices");
body("The count is already proven; only the reading is new. AP28 Propositions 1–2 establish the coupling structure of the arena: six faces of ε, three spatial dimensions, one Actualization State. Faces couple to dimensions — eighteen edges. The Actualization State couples to dimensions — three edges. Faces do not couple to the Actualization State — Proposition 2, the page and the pen. Twenty-one edges. And the same proven structure has 6 + 3 + 1 = **ten vertices**.");
body("The two costs of §1 are the two counts of this one graph. Leakage is transmission — an edge phenomenon: it flows along the couplings, per instant, C-bounded, twenty-one wide. Constitution is existence — a vertex phenomenon: the configuration is written into the elements themselves, once, R-recorded, ten deep. The corpus’s ten stands to its twenty-one as node to edge, as constitution to flow, as once to always. Nothing was added to obtain the ten. It was standing in AP28’s proof the whole time, waiting for the question that counts vertices instead of edges.");
body("Honesty about status, in two halves. The count is DERIVED — it is the vertex set of a proven graph. The assignment — the commitment distributed one share per vertex, compounding to the quotient of §5 — is MOTIVATED, not forced, and it is booked as such (D-CCC.2), the exact mirror of KS-30.4’s uniqueness debt in AP30. And the assignment is empirically silent: the distributed and undistributed forms differ by about 24 parts per million in G, below anything the laboratories can currently see. Because §4 fixes the total at one ε regardless of any distribution, nothing numerical in this paper rests on the vertices. They are architecture — the right architecture, this paper holds — and architecture is claimed as architecture, not smuggled in as arithmetic.");

// ============================== 9 ==============================
h1("9 — The Prediction");
body("The realised gravitational coupling is α_G* = α_em²¹ × (1 + 1/π) / (1 + α_em), and the realised constant is:");
body("**G = α_em²¹ × (1 + 1/π) / (1 + α_em) × ℏc / m_e²**", { align: AlignmentType.CENTER });
body("Using the CODATA inputs, as AP28 uses them:");
body("α_em²¹ = 1.338 × 10⁻⁴⁵", { align: AlignmentType.CENTER, after: 40 });
body("1 + 1/π = 1.31831", { align: AlignmentType.CENTER, after: 40 });
body("1 / (1 + α_em) = 0.992756", { align: AlignmentType.CENTER, after: 40 });
body("Structural value (AP28): G = 6.7206 × 10⁻¹¹ N·m²/kg²", { align: AlignmentType.CENTER, after: 40 });
body("**Realised value: G = 6.6719 × 10⁻¹¹ N·m²/kg²**", { align: AlignmentType.CENTER, after: 40 });
body("Measured (CODATA 2018, unchanged 2022): G = 6.6743 × 10⁻¹¹ N·m²/kg²", { align: AlignmentType.CENTER });
body("**Residual: −0.036%.**");
body("Read against the landscape rather than against a single number. AP28’s structural value stands 0.69% above the recommended value — thirteen times the roughly 500 ppm spread between independent laboratory determinations, outside every experiment ever performed. The realised value stands about 360 ppm below the recommended value — inside that spread, within one standard uncertainty of the lowest published determination and below others. The commitment closes about ninety-five per cent of the discrepancy and moves the prediction from outside the experimental landscape to its low edge. That is what the correction does. What it does not do is land on the recommended central value, and the paper says so in the same breath.");
body("The sign flip, stated plainly. Under AP28 alone, the gap ran prediction-above-measurement, the direction downward apparatus leakage can explain — Ø Predictions Part II says exactly this. Under the commitment, the residual runs prediction-below-measurement, and the same leakage mechanism cannot absorb it: leakage lowers what laboratories read; it cannot raise it. Adopting this paper therefore trades a large residual with a comfortable story for a small residual with no story yet. The residual is reported open and unattributed (§0.7): laboratory convergence toward the low determinations, a higher-order term in ε, or a refinement not yet forced. Which of these, the data will say — under the switches of §12 — and this paper will not say first.");

// ============================== 10 ==============================
h1("10 — What the Data May and May Not Do");
body("The rule is already corpus precedent, and this section only names it. In AP28, structure proposed three candidate normalisations — 1/π, 1/2π, 1/4π — and measurement eliminated two. The direction of that traffic is the entire discipline: **data may eliminate structural candidates; data may never generate them.** A number that arrives from the measurement side, however clean it looks, is a fitted parameter wearing a costume, and the corpus’s zero-fitted-parameters claim dies at the first one admitted.");
body("Applied here, the rule has teeth, because the whisper is real and it is fenced by being named. The empirically required commitment, computed backwards from the recommended central value, is 0.944 of one ε — and two clean fractions sit within reach of it: 20/21 of ε, which lands within about 60 ppm of the centre, and 17/18 of ε, which lands within a few ppm. Both arrived from the data. Neither has a forcing argument. Both come pre-dressed in a story — an exempt channel here, a refunded share there — and the stories are exactly as good as the fractions, which is to say: generated by the answer. They are recorded in this section for one purpose. Seen. Refused.");
body("And the target itself is soft, which is the final proof that digit-matching is meaningless here. Measured against the lowest laboratory determination the required fraction is 0.99 of ε; against the highest it is 0.92; the admissible window is the whole range between, four per cent wide against a formal uncertainty of 22 ppm. Any fraction in the window “fits”. Structure alone can choose, and structure already chose before the window was drawn: the axiom writes one element, once. This paper states 1×ε, states nothing finer, and arms KS-CCC.1 against every future refinement — including the author’s — that cannot show its forcing argument was written before its number.");

// ============================== 11 ==============================
h1("11 — Candidate Three");
body("Ø Predictions Part II holds the 0.69% open between two candidates and declines to pick: Candidate 1, apparatus leakage — the structural value is the unleaky value and every real measurement reads low; Candidate 2, refinement of the puncture normalisation under the KS-R.9 sub-debt. This paper enters as Candidate 3: the gap is neither in the apparatus nor in the puncture but in an unbooked provision — the structural value is the provisioned coupling, and what laboratories measure is the realised one.");
body("Candidate 3 does not merely join the list; it sharpens it, because Candidate 1 standing alone carries a strain its own published numbers expose. The gap is about 6,900 ppm. The spread between independent modern experiments is about 500 ppm. For apparatus leakage to carry the whole gap, torsion balances, beam balances and atom interferometers — radically different boundaries — would have to leak identically to within seven per cent of the effect. An apparatus effect that is over ninety per cent apparatus-independent is not an apparatus effect. It is universal, which is to say structural. Candidate 1, taken seriously, already implies a commitment-shaped universal term and a small genuinely-apparatus remainder — which is Candidate 3’s exact anatomy: a universal 1/(1 + ε), and a residual at scatter scale.");
body("The discriminator already exists in the corpus. Appendix C of Ø Predictions proposes the meta-analysis: characterise each published G experiment by its boundary geometry and test the leakage correlation. Under Candidate 1, the boundary-geometry corrections must come out near 6,900 ppm and correlate. Under Candidate 3, they must come out at scatter scale — hundreds of ppm at most. Same proposed experiment, opposite predictions, and KS-CCC.4 binds this paper to the outcome. Candidate 3 adds a falsification surface, not an escape hatch — which is the only way a third candidate earns entry into a register that was honest with two.");
body("On Candidate 2, this paper is indifferent at entry and constraining at exit. The commitment cannot rescue a wrong normalisation: carrying 1/2π to the measured value would require a commitment near eighteen ε, and 1/4π near twenty-nine — both structurally absurd. With the commitment live, 1/π remains uniquely selected among the enumerated candidates, exactly as before. The KS-R.9 sub-debt is untouched, and KS-CCC.6 states what happens if its resolution collides with §7.");

// ============================== 12 ==============================
h1("12 — Kill Switches");
body("Six switches, Claim / Test / Status / Recovery, identifiers pending MKSR registration.");
h2("KS-CCC.1 — Forced magnitude");
body("**Claim.** The commitment magnitude is 1×ε, stated from the axiom before any comparison with measurement, with no refinement admitted without a prior forcing argument.");
body("**Test.** The publication, anywhere in the corpus, of a commitment magnitude whose selection depended on comparison with measured G — including any fraction from §10’s fence.");
body("**Status.** LIVE — METHODOLOGICAL. This switch binds the author.");
body("**Recovery.** None inside the parameter-free claim. A fitted fraction retires the zero-fitted-parameters status of the G result; the correction reverts to 1×ε or is withdrawn entirely.");
h2("KS-CCC.2 — Ratio invariance");
body("**Claim.** The commitment cancels identically in every mass ratio; m_p/m_e carries no commitment signature above experimental uncertainty (±0.06 ppb).");
body("**Test.** Any derivation or measurement exhibiting a per-configuration commitment residue in a mass ratio.");
body("**Status.** LIVE — STRUCTURAL/EMPIRICAL.");
body("**Recovery.** Per-configuration fails, and with it the paper: a channel-scaled replacement is excluded by AP30 at eight orders of magnitude, so the proposal reverts to unpriced — AP28 §2’s sentence stands, the commitment withdrawn.");
h2("KS-CCC.3 — Direction");
body("**Claim.** The structural value exceeds the realised value; measured G lies at or above the realised prediction, never converging on the structural one.");
body("**Test.** Future metrology. Convergence upward toward 6.7206 × 10⁻¹¹ kills the commitment and revives Candidate 1 in full. Convergence near 6.672 × 10⁻¹¹ supports it.");
body("**Status.** LIVE — EMPIRICAL.");
body("**Recovery.** If metrology converges toward the structural value, the commitment is withdrawn and the 0.69% returns, whole, to Candidates 1 and 2.");
h2("KS-CCC.4 — The discriminator");
body("**Claim.** Apparatus-leakage corrections, characterised per Appendix C of Ø Predictions, are of scatter scale (at most hundreds of ppm), not of gap scale (~6,900 ppm).");
body("**Test.** The Appendix C meta-analysis itself.");
body("**Status.** LIVE — EMPIRICAL.");
body("**Recovery.** Gap-scale corrections confirm Candidate 1 and withdraw the commitment; the realised formula reverts to AP28’s.");
h2("KS-CCC.5 — Held, not shed");
body("**Claim.** The constitution instant’s ε is held as the persistence commitment (Proposition 2).");
body("**Test.** Exhibit a mechanism by which the constitution ε is shed while the constitution record is held open by other means.");
body("**Status.** LIVE — STRUCTURAL.");
body("**Recovery.** Proposition 2 fails; the dichotomy collapses to leakage-only; the commitment is withdrawn. AP06 is unaffected — the leakage never depended on this paper.");
h2("KS-CCC.6 — Single entry");
body("**Claim.** The puncture factor and the commitment are independent readings of the unpaired element (Proposition 6).");
body("**Test.** The completed puncture-topology normalisation owed under KS-R.9, if it is shown to already contain the persistence provision.");
body("**Status.** LIVE — STRUCTURAL, coupled to KS-R.9.");
body("**Recovery.** The correction double-counts and is removed; the puncture factor absorbs the commitment under a reinterpreted normalisation; the realised formula reverts to AP28’s.");

// ============================== 13 ==============================
h1("13 — Dependencies");
body("**Depends on:** AP06 (Identification 6.1; the leakage as shed ε). AP28 (the coupling graph; the per-channel coupling; the R-reading of G; the no-selective-persistence clause). AP24 (the many-readings licence). AP10 (three dimensions; the 1:1 as substrate). AP43 D5 (one ε per instant). AP29 (mass as coupling capacity actualised). AP20 (independence; the unconditional floor).");
body("**What depends on it:** Nothing, until adoption. On adoption: AP28 §6–§7 and the wording of KS-R.7; Ø Predictions Part II (a third candidate; the sign flip of the residual; Appendix C read as the discriminator); the G passages of the Proofs (Chapters 16 and 19) and of the Prose and Metaphor registers; every dependent of the holding limit κ, per the D-CCC.3 audit; and the Master Kill Switch Registry, which advances by six switches. Adoption is a coordinated amendment sequenced by an update table, in the discipline the corpus already uses — not a patch, and not before the author’s ruling.");

// ============================== CLAIM SUMMARY ==============================
h1("Claim Summary");
body("**§2 — Constitution record.**  Every persisting configuration has a unique first record. DERIVED.");
body("**§3 — Held, not shed.**  The constitution instant’s ε is held as the persistence commitment; every later instant’s ε is shed as leakage. DERIVED — structural register; formalisation owed (D-CCC.1).");
body("**§4 — One snap, one ε.**  The commitment is per configuration, forced by the no-selective-persistence clause; it cancels identically in every mass ratio. DERIVED; corollary guarded by KS-CCC.2.");
body("**§5 — Realised over provisioned.**  α_G* = α_G / (1 + ε), the quotient read off the axiom; ε = α_em inherited from Identification 6.1. DERIVED.");
body("**§6 — Placement.**  The commitment divides the coupling; mass-side dressing eliminated twice (unforced ½; AP29 double count). SELECTED AMONG STRUCTURAL CANDIDATES.");
body("**§7 — Double entry.**  Contribution (1 + 1/π) and commitment 1/(1 + ε) are two readings of one element, under AP24’s licence. STRUCTURAL; guarded by KS-CCC.6.");
body("**§8 — Vertices.**  Ten vertices, twenty-one edges of AP28’s proven graph; constitution at nodes, flow along edges. DERIVED count; MOTIVATED assignment; empirically silent.");
body("**§9 — Prediction.**  G = 6.6719 × 10⁻¹¹; residual −0.036%, sign flipped, reported open. EMPIRICAL.");
body("**§10 — The rule.**  Data eliminates; data never generates. The fenced fractions recorded and refused. METHOD.");
body("**§11 — Candidate three.**  Entry into Ø Predictions’ open register with its own discriminator. STRUCTURAL PLACEMENT.");

// ============================== CONDITIONALITY FOOTER ==============================
h1("Conditionality Footer");
h2("Dependencies");
body("AP06 (Identification 6.1). AP28 (coupling graph; R-reading; §4 clause). AP24 (many-readings licence). AP10 (dimensions; the 1:1 as substrate). AP43 D5 (one ε per instant). AP29 (E ≡ κ(B) · AS). AP20 (independence). This paper is unconditional on EH and QRA.");
h2("Dependents");
body("None until adoption. On adoption: AP28 §6–§7, KS-R.7 wording, Ø Predictions Part II and Appendix C, Proofs Chapters 16 and 19, the Prose and Metaphor G passages, all κ dependents (D-CCC.3), the MKSR.");
h2("Kill switches engaged");
body("KS-CCC.1 (forced magnitude, LIVE — METHODOLOGICAL). KS-CCC.2 (ratio invariance, LIVE — STRUCTURAL/EMPIRICAL). KS-CCC.3 (direction, LIVE — EMPIRICAL). KS-CCC.4 (discriminator, LIVE — EMPIRICAL). KS-CCC.5 (held not shed, LIVE — STRUCTURAL). KS-CCC.6 (single entry, LIVE — STRUCTURAL, coupled to KS-R.9).");
h2("Structural debts owed");
body("D-CCC.1 (record-algebra formalisation of the held commitment — load-bearing for grade). D-CCC.2 (vertex-assignment uniqueness — non-load-bearing). D-CCC.3 (κ-dependents audit before adoption). D-CCC.4 (exhaustiveness of the placement enumeration).");
h2("Items held open without claiming debt status");
body("Attribution of the −0.036% residual. The ε²-order difference between quotient and shadow (53 ppm). The empirical silence of the vertex distribution (24 ppm). The adoption update table, owed on adoption.");

// ============================== NOTATION ==============================
h1("Notation Reference");
body("**1:1 + 1×ε @ AS**  —  The axiom. The balance, the one unpaired element, read at the Actualization State.");
body("**ε**  —  The unique unpaired element of Axiom B. Value at the coupling boundary: α_em (Identification 6.1, AP06).");
body("**α_em**  —  The fine-structure constant ≈ 1/137.036. The per-channel coupling (AP28) and the leakage rate (AP06).");
body("**α_G**  —  The structural gravitational coupling, α_em²¹ × (1 + 1/π) (AP28). The provisioned coupling.");
body("**α_G***  —  The realised gravitational coupling, α_G / (1 + ε). Introduced in this paper.");
body("**κ, κ***  —  The holding limit and its realised value, κ* = α_G* ℏc / 2.");
body("**G**  —  Newton’s constant. Realised: G = α_G* ℏc / m_e² = 6.6719 × 10⁻¹¹ N·m²/kg².");
body("**snap**  —  The constitution event: the single AS-instant at which a configuration’s first record is written and holds.");
body("**commitment (CCC)**  —  The constitution instant’s ε, held once as the price of persistence. G-denominated.");
body("**leakage (TLC)**  —  Every subsequent instant’s ε, shed at the boundary. c-denominated (AP06).");
body("**provisioned / realised**  —  The axiom’s two totals: 1:1 + 1×ε, and the persisting 1:1.");
body("**vertex / edge**  —  The two counts of AP28’s proven coupling graph: 6 + 3 + 1 = 10 vertices; 18 + 3 = 21 edges.");
body("**Actualization State (AS)**  —  The actualising now: the surface from which records are written (AP01).");
spacer(200);
center("This work is published for free, forever.", 20, 60, false, true);
center("End of The Snap. Draft v0.1 — unlocked.", 20, 0, false, true);

// ============================== BUILD ==============================
