{"language": "javascript", "code": "const fs = require("fs");
const {
  Document, Packer, Paragraph, TextRun, AlignmentType, Table, TableRow, TableCell,
  WidthType, BorderStyle, ShadingType, HeadingLevel
} = require("docx");

const FONT = "Garamond";

// ---------- inline markdown-ish parser: **bold**, *italic* ----------
function runs(text, base = {}) {
  const out = [];
  const re = /(\*\*[^*]+\*\*|\*[^*]+\*)/g;
  let last = 0, m;
  while ((m = re.exec(text)) !== null) {
    if (m.index > last) out.push(new TextRun({ text: text.slice(last, m.index), font: FONT, ...base }));
    const tok = m[0];
    if (tok.startsWith("**")) out.push(new TextRun({ text: tok.slice(2, -2), bold: true, font: FONT, ...base }));
    else out.push(new TextRun({ text: tok.slice(1, -1), italics: true, font: FONT, ...base }));
    last = m.index + tok.length;
  }
  if (last < text.length) out.push(new TextRun({ text: text.slice(last), font: FONT, ...base }));
  return out;
}

const P = [];
function body(text, opts = {}) {
  P.push(new Paragraph({
    children: runs(text, { size: opts.size || 22 }),
    alignment: opts.align || AlignmentType.JUSTIFIED,
    spacing: { after: opts.after ?? 160, line: 276 },
  }));
}
function center(text, size = 22, after = 80, bold = false, italics = false) {
  P.push(new Paragraph({
    children: [new TextRun({ text, font: FONT, size, bold, italics })],
    alignment: AlignmentType.CENTER, spacing: { after },
  }));
}
function h1(text) {
  P.push(new Paragraph({
    children: runs(text, { size: 28, bold: true }),
    spacing: { before: 320, after: 160 }, heading: HeadingLevel.HEADING_1,
  }));
}
function h2(text) {
  P.push(new Paragraph({
    children: runs(text, { size: 24, bold: true }),
    spacing: { before: 240, after: 120 }, heading: HeadingLevel.HEADING_2,
  }));
}
function spacer(pts = 120) { P.push(new Paragraph({ children: [], spacing: { after: pts } })); }

// ============================== TITLE BLOCK ==============================
center("[ Eye of the Universe ]", 22, 60, false, true);
center("The 420 Code", 22, 60, false, true);
